import { useEffect } from 'react';
import { useCollection, useField } from 'qortex-resource-react';
import type { Resource } from 'qortex-resource';

type Task = { id: string; title: string; done: boolean };

export function TaskBoard({ projectId }: { projectId: string }) {
  // Remount = fresh collection when project changes
  return <TaskList key={projectId} projectId={projectId} />;
}

function TaskList({ projectId }: { projectId: string }) {
  const { items, setAll, addOne, removeOne, getResource } = useCollection<Task>({
    getId: (t) => t.id,
  });

  useEffect(() => {
    let cancelled = false;
    api.tasks.list(projectId).then((rows) => {
      if (!cancelled) setAll(rows);
    });
    return () => { cancelled = true; };
  }, [projectId, setAll]);

  return (
    <div>
      <button
        type="button"
        onClick={() =>
          addOne({ id: crypto.randomUUID(), title: 'New task', done: false })
        }
      >
        Add task
      </button>
      <ul>
        {items.map((t) => (
          <TaskRow
            key={t.id}
            resource={getResource(t.id)}
            onRemove={() => removeOne(t.id)}
          />
        ))}
      </ul>
    </div>
  );
}

function TaskRow({
  resource,
  onRemove,
}: {
  resource: Resource<Task>;
  onRemove: () => void;
}) {
  // Subscribe only this row's fields — sibling rows do not re-render
  const title = useField(resource, 'title');
  const done = useField(resource, 'done');

  return (
    <li>
      <input
        type="checkbox"
        checked={!!done.value}
        onChange={(e) => done.onChange(e.target.checked)}
      />
      <input
        value={title.value ?? ''}
        onChange={(e) => title.onChange(e.target.value)}
        onBlur={title.onBlur}
      />
      <button
        type="button"
        disabled={!resource.snapshot.isChanged}
        onClick={() => resource.save()}
      >
        Save row
      </button>
      <button type="button" onClick={onRemove}>Delete</button>
    </li>
  );
}

// After getResource(id), you can still call your API from the row:
async function saveRow(resource: Resource<Task>) {
  const result = await resource.save();
  if (result.ok) {
    await api.tasks.update(resource.snapshot.data!.id, resource.snapshot.data!);
  }
}

